/* Kodama Grove Theme — Tailwind v3 (rgb) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Kodama Grove Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 227 215 179;
    --foreground: 93 76 64;
    --card: 230 218 189;
    --card-foreground: 93 76 64;
    --popover: 243 235 213;
    --popover-foreground: 93 76 64;
    --primary: 142 159 76;
    --primary-foreground: 254 252 244;
    --secondary: 220 205 161;
    --secondary-foreground: 93 76 64;
    --muted: 220 205 161;
    --muted-foreground: 136 119 105;
    --accent: 220 201 150;
    --accent-foreground: 93 76 64;
    --destructive: 217 137 124;
    --destructive-foreground: 251 248 241;
    --border: 175 150 131;
    --input: 220 201 150;
    --ring: 155 176 137;
    --chart-1: 155 176 137;
    --chart-2: 138 161 122;
    --chart-3: 187 201 182;
    --chart-4: 111 133 104;
    --chart-5: 94 111 88;
    --radius: 0.425rem;
    --sidebar: 224 208 165;
    --sidebar-foreground: 93 76 64;
    --sidebar-primary: 155 176 137;
    --sidebar-primary-foreground: 254 252 244;
    --sidebar-accent: 234 228 214;
    --sidebar-accent-foreground: 93 76 64;
    --sidebar-border: 231 225 211;
    --sidebar-ring: 155 176 137;
    --font-sans: Merriweather, serif;
    --font-serif: Source Serif 4, serif;
    --font-mono: JetBrains Mono, monospace;
    --shadow-color: 91 109 70;
    --shadow-opacity: 0.15;
    --shadow-blur: 2px;
    --shadow-spread: 0px;
    --shadow-offset-x: 3px;
    --shadow-offset-y: 3px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 3px 3px 2px 0px hsl(88 22% 35% / 0.07);
    --shadow-xs: 3px 3px 2px 0px hsl(88 22% 35% / 0.07);
    --shadow-sm:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 1px 2px -1px hsl(88 22% 35% / 0.15);
    --shadow:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 1px 2px -1px hsl(88 22% 35% / 0.15);
    --shadow-md:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 2px 4px -1px hsl(88 22% 35% / 0.15);
    --shadow-lg:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 4px 6px -1px hsl(88 22% 35% / 0.15);
    --shadow-xl:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 8px 10px -1px hsl(88 22% 35% / 0.15);
    --shadow-2xl: 3px 3px 2px 0px hsl(88 22% 35% / 0.38);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 58 53 42;
    --foreground: 235 228 214;
    --card: 66 60 49;
    --card-foreground: 235 228 214;
    --popover: 66 60 49;
    --popover-foreground: 235 228 214;
    --primary: 138 161 122;
    --primary-foreground: 42 37 34;
    --secondary: 88 82 70;
    --secondary-foreground: 235 228 214;
    --muted: 74 68 57;
    --muted-foreground: 169 160 148;
    --accent: 159 142 93;
    --accent-foreground: 42 37 34;
    --destructive: 180 119 107;
    --destructive-foreground: 241 234 220;
    --border: 88 82 70;
    --input: 88 82 70;
    --ring: 138 161 122;
    --chart-1: 138 161 122;
    --chart-2: 155 176 137;
    --chart-3: 111 133 104;
    --chart-4: 159 142 93;
    --chart-5: 94 111 88;
    --radius: 0.425rem;
    --sidebar: 58 53 42;
    --sidebar-foreground: 235 228 214;
    --sidebar-primary: 138 161 122;
    --sidebar-primary-foreground: 42 37 34;
    --sidebar-accent: 159 142 93;
    --sidebar-accent-foreground: 42 37 34;
    --sidebar-border: 88 82 70;
    --sidebar-ring: 138 161 122;
    --font-sans: Merriweather, serif;
    --font-serif: Source Serif 4, serif;
    --font-mono: JetBrains Mono, monospace;
    --shadow-color: 91 109 70;
    --shadow-opacity: 0.15;
    --shadow-blur: 2px;
    --shadow-spread: 0px;
    --shadow-offset-x: 3px;
    --shadow-offset-y: 3px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 3px 3px 2px 0px hsl(88 22% 35% / 0.07);
    --shadow-xs: 3px 3px 2px 0px hsl(88 22% 35% / 0.07);
    --shadow-sm:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 1px 2px -1px hsl(88 22% 35% / 0.15);
    --shadow:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 1px 2px -1px hsl(88 22% 35% / 0.15);
    --shadow-md:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 2px 4px -1px hsl(88 22% 35% / 0.15);
    --shadow-lg:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 4px 6px -1px hsl(88 22% 35% / 0.15);
    --shadow-xl:
      3px 3px 2px 0px hsl(88 22% 35% / 0.15),
      3px 8px 10px -1px hsl(88 22% 35% / 0.15);
    --shadow-2xl: 3px 3px 2px 0px hsl(88 22% 35% / 0.38);
  }

}
